CREATE TABLE products (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_id BIGINT UNSIGNED NOT NULL,
  name VARCHAR(120) NOT NULL,
  price DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  attributes JSON NULL COMMENT '颜色、尺码等扩展属性',
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO products (category_id, name, price, attributes)
VALUES (2, '纯棉 T 恤', 79.00, '{"color": "red", "size": ["M", "L", "XL"]}');

SELECT id, name, attributes->>'$.color' AS color
FROM products
WHERE JSON_CONTAINS(attributes, '"red"', '$.color');

ALTER TABLE products
  ADD COLUMN color VARCHAR(20)
    GENERATED ALWAYS AS (attributes->>'$.color') STORED,
  ADD KEY idx_color (color);

SELECT id, name FROM products WHERE color = 'red';
